#!/usr/bin/env node

const express = require("express");
const { alldl } = require("../index.js");

const UI_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>📥 Rahad Downloader API</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#0f0f1a;color:#fff;min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:40px 20px}
h1{font-size:2.2rem;margin-bottom:8px;background:linear-gradient(135deg,#667eea,#764ba2);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.sub{color:#888;margin-bottom:32px}
.card{background:#1a1a2e;border:1px solid #2d2d44;border-radius:16px;padding:28px;width:100%;max-width:560px;box-shadow:0 8px 32px rgba(0,0,0,.4)}
input[type=text]{width:100%;padding:14px 16px;border-radius:10px;border:1px solid #2d2d44;background:#0f0f1a;color:#fff;font-size:15px;margin-bottom:14px;outline:none}
input[type=text]:focus{border-color:#667eea}
.row{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}
select{background:#0f0f1a;color:#fff;border:1px solid #2d2d44;border-radius:10px;padding:10px 14px;font-size:14px;outline:none}
label.chk{display:flex;align-items:center;gap:8px;font-size:14px;color:#aaa;cursor:pointer}
button{width:100%;padding:14px;border:none;border-radius:10px;background:linear-gradient(135deg,#667eea,#764ba2);color:#fff;font-size:16px;font-weight:600;cursor:pointer;transition:transform .1s}
button:hover{transform:translateY(-1px)}
button:disabled{opacity:.5;cursor:wait;transform:none}
#result{margin-top:18px;display:none}
#result.show{display:block}
.meta{background:#0f0f1a;border-radius:10px;padding:14px;margin-bottom:12px;font-size:14px}
.meta b{color:#667eea}
.dlbtn{display:block;text-align:center;text-decoration:none;padding:12px;border-radius:10px;background:#22c55e;color:#fff;font-weight:600;margin-top:10px}
.err{color:#f87171;background:#2a1215;border-radius:10px;padding:12px;font-size:14px}
.platforms{margin-top:28px;color:#666;font-size:13px;text-align:center;line-height:1.8}
code{background:#1a1a2e;padding:2px 8px;border-radius:6px;font-size:13px}
.footer{margin-top:24px;color:#555;font-size:12px}
.spinner{display:inline-block;width:16px;height:16px;border:2px solid #fff3;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite;vertical-align:-3px;margin-right:8px}
@keyframes spin{to{transform:rotate(360deg)}}
</style>
</head>
<body>
<h1>📥 Rahad Downloader</h1>
<p class="sub">One package. Every platform. Your own API.</p>
<div class="card">
<input type="text" id="url" placeholder="Paste TikTok / Instagram / YouTube / X link here..." autocomplete="off">
<div class="row">
<select id="quality">
<option value="best">Best quality</option>
<option value="high">High</option>
<option value="medium">Medium</option>
<option value="low">Low (small file)</option>
</select>
<label class="chk"><input type="checkbox" id="audio"> 🎵 Audio only (MP3)</label>
</div>
<button id="go" onclick="go()">Download</button>
<div id="result"></div>
</div>
<div class="platforms">
TikTok · Instagram · Facebook · YouTube · X · Snapchat · Threads · Pinterest · Likee · CapCut · Kwai · Dailymotion · Vimeo<br>
API: <code>POST /api/download</code> &nbsp; <code>POST /api/info</code> &nbsp; <code>GET /api/file?url=</code>
</div>
<p class="footer">rahad-all-downloader-v2 · self-hosted</p>
<script>
const KEY = new URLSearchParams(location.search).get('key') || '';
async function go(){
  const url = document.getElementById('url').value.trim();
  if(!url) return;
  const btn = document.getElementById('go'), res = document.getElementById('result');
  btn.disabled = true; btn.innerHTML = '<span class="spinner"></span>Working...';
  res.className = ''; res.innerHTML = '';
  try{
    const r = await fetch('/api/download', {
      method:'POST',
      headers:{'Content-Type':'application/json', ...(KEY?{'x-api-key':KEY}:{})},
      body: JSON.stringify({ url, quality: document.getElementById('quality').value, audioOnly: document.getElementById('audio').checked })
    });
    const d = await r.json();
    if(d.status !== 'success') throw new Error(d.response || 'Failed');
    res.className = 'show';
    res.innerHTML = '<div class="meta"><b>📌</b> ' + esc(d.title) + '<br><b>📡</b> ' + esc(d.source) + '</div>' +
      '<a class="dlbtn" href="/api/file?url=' + encodeURIComponent(d.videoUrl) + (KEY?'&key='+encodeURIComponent(KEY):'') + '&title=' + encodeURIComponent(d.title||'video') + '" download>⬇️ Download File</a>' +
      '<a class="dlbtn" style="background:#1a1a2e;border:1px solid #2d2d44;margin-top:8px" href="' + esc(d.videoUrl) + '" target="_blank">🔗 Direct Link</a>';
  }catch(e){
    res.className = 'show';
    res.innerHTML = '<div class="err">❌ ' + esc(e.message) + '</div>';
  }
  btn.disabled = false; btn.textContent = 'Download';
}
function esc(s){return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.getElementById('url').addEventListener('keydown', e => { if(e.key === 'Enter') go(); });
</script>
</body>
</html>`;

function startServer(opts = {}) {
  const app = express();
  const PORT = opts.port || 3000;
  const API_KEY = opts.apiKey || null;

  app.use(express.json({ limit: "1mb" }));

  app.use("/api/", (req, res, next) => {
    if (!API_KEY) return next();
    const key = req.headers["x-api-key"] || req.query.key;
    if (key !== API_KEY) return res.status(401).json({ status: "error", response: "Invalid API key." });
    next();
  });

  app.get("/", (req, res) => res.type("html").send(UI_HTML));
  app.get("/api/health", (req, res) => res.json({ status: "ok", version: require("../package.json").version }));

  app.post("/api/info", async (req, res) => {
    const url = String(req.body?.url || "").trim();
    if (!/^https?:\/\//i.test(url)) return res.status(400).json({ status: "error", response: "Valid URL required." });
    try {
      const r = await alldl.info(url);
      res.json({ status: "success", ...r });
    } catch (e) {
      res.status(500).json({ status: "error", response: e.message });
    }
  });

  app.post("/api/download", async (req, res) => {
    const url = String(req.body?.url || "").trim();
    const quality = req.body?.quality || "best";
    const audioOnly = !!req.body?.audioOnly;
    if (!/^https?:\/\//i.test(url)) return res.status(400).json({ status: "error", response: "Valid URL required." });
    try {
      const r = await Promise.race([
        alldl(url, { quality: audioOnly ? "audio" : quality }),
        new Promise((_, rej) => setTimeout(() => rej(new Error("Resolve timeout (45s)")), 45000)),
      ]);
      const videoUrl = r?.data?.videoUrl;
      if (!videoUrl) return res.status(502).json({ status: "error", response: "Could not extract a download link." });
      res.json({ status: "success", title: r.data.title, source: r.data.source, videoUrl, quality, audioOnly });
    } catch (e) {
      res.status(500).json({ status: "error", response: e.message });
    }
  });

  app.get("/api/file", async (req, res) => {
    const fileUrl = String(req.query.url || "");
    const title = String(req.query.title || "video").replace(/[^\w\s-]/g, "").slice(0, 80) || "video";
    if (!/^https?:\/\//i.test(fileUrl)) return res.status(400).json({ status: "error", response: "Valid url param required." });
    try {
      const axios = require("axios");
      const upstream = await axios({
        url: fileUrl, method: "GET", responseType: "stream",
        timeout: 120000, maxRedirects: 5,
        headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" },
        validateStatus: (s) => s >= 200 && s < 400,
      });
      const ext = (upstream.headers["content-type"] || "").includes("audio") ? "mp3" : "mp4";
      res.setHeader("Content-Disposition", `attachment; filename="${title}.${ext}"`);
      if (upstream.headers["content-type"]) res.setHeader("Content-Type", upstream.headers["content-type"]);
      upstream.data.pipe(res);
    } catch (e) {
      res.status(502).json({ status: "error", response: "File fetch failed: " + e.message });
    }
  });

  return new Promise((resolve) => {
    const server = app.listen(PORT, () => {
      console.log(`\n🚀 Rahad Downloader API running!`);
      console.log(`   🌐 Web UI : http://localhost:${PORT}`);
      console.log(`   🔌 API    : http://localhost:${PORT}/api/download`);
      if (API_KEY) console.log(`   🔑 API key : enabled`);
      console.log(``);
      resolve(server);
    });
  });
}

module.exports = { startServer };

if (require.main === module) {
  const args = process.argv.slice(2);
  const get = (f) => {
    const i = args.indexOf(f);
    return i !== -1 && args[i + 1] ? args[i + 1] : null;
  };
  const port = parseInt(get("--port") || process.env.PORT || "3000", 10);
  const apiKey = get("--api-key") || process.env.RAHAD_API_KEY || null;
  const proxy = get("--proxy") || process.env.RAHAD_PROXY || null;
  if (proxy) {
    alldl.setProxy(proxy);
    console.log(`🌍 Proxy: ${proxy.replace(/:[^:@/]*@/, ":***@")}`);
  }
  startServer({ port, apiKey });
}
